html:
{%- from "templates/print_formats/standard_macros.html" import add_header -%}
{{ add_header(0, 1, doc, letter_head, no_letterhead, footer, print_settings) }}
<style>
.al-doc { font-size: 11px; color: #1f2933; }
.al-doc h2 { font-size: 18px; margin: 0 0 2px; letter-spacing: .02em; }
.al-doc .al-sub { color: #52606d; margin-bottom: 12px; }
.al-doc table { width: 100%; border-collapse: collapse; margin: 8px 0 12px; }
.al-doc th { background: #f0f2f5; text-align: left; font-weight: 600; }
.al-doc th, .al-doc td { border: 1px solid #cbd2d9; padding: 4px 6px; vertical-align: top; }
.al-doc .al-grid td { border: none; padding: 2px 8px 2px 0; }
.al-doc .al-label { color: #52606d; width: 22%; }
.al-doc .num { text-align: right; white-space: nowrap; }
.al-doc .al-worse { font-weight: 700; text-decoration: underline; }
.al-doc .al-sign { margin-top: 36px; }
.al-doc .al-sign td { border: none; border-top: 1px solid #52606d; width: 25%; padding-top: 4px; text-align: center; }
.al-doc .al-note { border-left: 3px solid #9aa5b1; padding: 4px 8px; color: #3e4c59; margin: 8px 0; }
</style>
{%- set company = frappe.db.get_value("Company", doc.company, ["company_name", "tax_id"], as_dict=True) -%}
<div class="al-doc">
<h2>{{ _("Tax Invoice") }}</h2>
<div class="al-sub">{{ doc.name }} &middot; {{ doc.get_formatted("posting_date") }}{% if doc.al_invoice_purpose and doc.al_invoice_purpose != "Standard" %} &middot; {{ _(doc.al_invoice_purpose) }}{% endif %}</div>
<table class="al-grid">
<tr><td class="al-label">{{ _("Supplier") }}</td><td><b>{{ company.company_name }}</b>{% if company.tax_id %}<br>{{ _("Tax ID") }}: {{ company.tax_id }}{% endif %}{% if doc.company_address_display %}<br>{{ doc.company_address_display }}{% endif %}</td>
<td class="al-label">{{ _("Bill to") }}</td><td><b>{{ doc.customer_name }}</b>{% if doc.tax_id %}<br>{{ _("Tax ID") }}: {{ doc.tax_id }}{% endif %}{% if doc.address_display %}<br>{{ doc.address_display }}{% endif %}</td></tr>
<tr><td class="al-label">{{ _("Rental agreement") }}</td><td>{{ doc.al_rental_agreement or "" }}</td>
<td class="al-label">{{ _("Hire period") }}</td><td>{% if doc.from_date %}{{ doc.get_formatted("from_date") }} {{ _("to") }} {{ doc.get_formatted("to_date") }}{% endif %}</td></tr>
<tr><td class="al-label">{{ _("Due date") }}</td><td>{{ doc.get_formatted("due_date") }}</td><td class="al-label">{{ _("Place of supply") }}</td><td>{{ doc.get("place_of_supply") or "" }}</td></tr>
</table>
<table>
<tr><th>#</th><th>{{ _("Description") }}</th><th>{{ _("Equipment") }}</th><th>{{ _("HSN/SAC") }}</th><th class="num">{{ _("Days") }}</th><th class="num">{{ _("Amount") }}</th></tr>
{% for row in doc.items %}
<tr><td>{{ row.idx }}</td><td><b>{{ row.item_name }}</b><br>{{ row.description if row.description != row.item_name else "" }}</td>
<td>{{ row.al_asset or "" }}</td><td>{{ row.get("gst_hsn_code") or "" }}</td>
<td class="num">{{ row.al_billable_days or "" }}</td><td class="num">{{ row.get_formatted("net_amount", doc) }}</td></tr>
{% endfor %}
</table>
<table class="al-grid" style="width: 45%; margin-left: 55%;">
<tr><td class="al-label">{{ _("Taxable value") }}</td><td class="num">{{ doc.get_formatted("net_total") }}</td></tr>
{% for tax in doc.taxes %}{% if tax.tax_amount %}<tr><td class="al-label">{{ tax.description }}</td><td class="num">{{ tax.get_formatted("tax_amount", doc) }}</td></tr>{% endif %}{% endfor %}
{% if doc.discount_amount %}<tr><td class="al-label">{{ _("Discount") }}</td><td class="num">- {{ doc.get_formatted("discount_amount") }}</td></tr>{% endif %}
<tr><td class="al-label"><b>{{ _("Total") }}</b></td><td class="num"><b>{{ doc.get_formatted("rounded_total" if doc.rounded_total else "grand_total") }}</b></td></tr>
</table>
<div>{{ _("Amount in words") }}: {{ doc.in_words }}</div>
{% if doc.terms %}<div class="al-note">{{ doc.terms }}</div>{% endif %}
<table class="al-sign"><tr><td></td><td></td><td></td><td>{{ _("For") }} {{ company.company_name }}</td></tr></table>
</div>
